const OFFICIAL_LOGO='https://a-us.storyblok.com/f/1003963/768x560/6b42f40fcf/logo-thumbnail.png';
const OFFICIAL_HERO='https://res.cloudinary.com/flyzipline/video/upload/q_auto,f_auto,so_0/v1776784625/homepage_hero_desktop_21042026_rw2jvh.jpg';
const OFFICIAL_PHARMA_VIDEO='https://a-us.storyblok.com/f/1003963/x/8a10db9118/scotts-pharma_x.mp4';
const OFFICIAL_FLEET_VIDEO='https://a-us.storyblok.com/f/1003963/x/2a95878cf5/39-zips-alternate.mp4';
const state={token:localStorage.getItem('cccHubToken')||'',data:null,view:'home',commFilter:'all',docFilter:'all',courseFilter:'all',adminTab:'overview',adminUsers:null,analytics:null,detail:null};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
const fmt=d=>d?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(new Date(d)):'—';
const fmtTime=d=>d?new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(d)):'—';
const toArray=v=>Array.isArray(v)?v:[];
const toast=msg=>{const el=$('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)};
const empty=t=>`<div class="empty-state">${esc(t)}</div>`;
function roleName(r){return r==='admin'?'Admin':r==='editor'?'Editor':'Viewer'}
async function api(path='',opts={}){
  const headers={...(opts.body?{'content-type':'application/json'}:{}),...(state.token?{'authorization':`Bearer ${state.token}`}:{}) ,...(opts.headers||{})};
  const res=await fetch(`/api/${path}`,{...opts,headers});
  const body=await res.json().catch(()=>({}));
  if(res.status===401&&state.token){logout(false);throw new Error('Your session expired. Please sign in again.');}
  if(!res.ok)throw new Error(body.error||'Request failed');return body;
}
function setAuthPanel(which){['login','signup','reset'].forEach(x=>$(`#${x}Panel`).classList.toggle('hidden',x!==which));$('#authMessage').textContent='';}
function showApp(show){$('#authScreen').classList.toggle('hidden',show);$('#appShell').classList.toggle('hidden',!show);}
async function bootstrap(){if(!state.token){showApp(false);return}try{const out=await api('data');state.data=out.data;showApp(true);afterLoad();}catch(e){showApp(false);$('#authMessage').textContent=e.message;}}
function afterLoad(){updateProfile();renderAll();}
async function dismissNotification(id){if(!id)return;try{const out=await api('notifications/read',{method:'POST',body:JSON.stringify({id})});state.data=out.data;updateProfile();renderNotifications();renderHome();}catch(err){toast(err.message)}}
async function dismissAllNotifications(){try{const out=await api('notifications/read',{method:'POST',body:JSON.stringify({all:true})});state.data=out.data;updateProfile();renderNotifications();renderHome();toast('Notifications cleared');}catch(err){toast(err.message)}}
function updateProfile(){const me=state.data.me;$('#profileName').textContent=me.name;$('#profileRole').textContent=roleName(me.role);$('#profileInitial').textContent=(me.name||'U').trim()[0].toUpperCase();$('#adminNav').classList.toggle('hidden',me.role!=='admin');$$('.editor-only').forEach(x=>x.classList.toggle('hidden',!['editor','admin'].includes(me.role)));const n=toArray(state.data.notifications).length;$('#notificationBadge').textContent=n;$('#notificationBadge').classList.toggle('hidden',!n);}
function renderAll(){renderHome();renderCommunications();renderKnowledge();renderLearning();renderDecisions();renderNotifications();if(state.data.me.role==='admin'&&state.view==='admin')renderAdmin();}
function setView(v){if(v==='admin'&&state.data.me.role!=='admin')return;state.view=v;$$('.view').forEach(x=>x.classList.toggle('active',x.id===`${v}View`));$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v));const titles={home:'Home',communications:'Communications',knowledge:'Knowledge',learning:'Learning',decisions:'Decisions',admin:'Admin',search:'Search'};$('#viewTitle').textContent=titles[v]||'Home';$('#viewEyebrow').textContent=v==='admin'?'CONTROL CENTER':'CENTRALIZED CALL CENTER';$('#quickCreate').classList.toggle('hidden',!['editor','admin'].includes(state.data.me.role)||!['communications','knowledge','decisions'].includes(v));if(v==='admin')loadAdminData();}
function progressOf(c){return c.progress||{percent:0,completed:false,total:0,completedCount:0}}
function isUnread(u){return !toArray(u.acknowledgements).some(a=>a.userId===state.data.me.id||(!a.userId&&a.name===state.data.me.name));}
function renderHome(){const d=state.data,active=d.updates.filter(x=>x.status==='Active').length,unread=d.updates.filter(x=>x.status==='Active'&&isUnread(x)).length,due=d.courses.filter(x=>!progressOf(x).completed&&x.dueDate&&new Date(x.dueDate)<new Date()).length,knowledge=d.docs.filter(x=>x.status!=='Archived').length;$('#homeStats').innerHTML=[[active,'Active updates'],[unread,'Unread updates'],[due,'Overdue learning'],[knowledge,'Knowledge items']].map(([n,l])=>`<div class="stat-card"><strong>${n}</strong><span>${l}</span></div>`).join('');
  const pinned=d.updates.filter(x=>x.pinned&&x.status==='Active').slice(0,4);$('#pinnedUpdates').innerHTML=pinned.length?pinned.map(u=>listRow('updates',u.id,u.title,`${u.category} · ${u.mandatory?'Acknowledgement required':'Pinned'}`,u.priority)).join(''):empty('No pinned communications right now.');
  const courses=d.courses.filter(c=>!progressOf(c).completed).slice(0,4);$('#homeLearning').innerHTML=courses.length?courses.map(c=>`<div class="list-row clickable" data-course-id="${c.id}"><div><strong>${esc(c.title)}</strong><small>${progressOf(c).percent}% complete${c.dueDate?` · Due ${fmt(c.dueDate)}`:''}</small></div><span class="pill ${c.dueDate&&new Date(c.dueDate)<new Date()?'Critical':''}">${c.required?'Required':'Learning'}</span></div>`).join(''):empty('You are caught up.');
  const att=toArray(d.notifications).slice(0,6);$('#attentionList').innerHTML=att.length?att.map(n=>`<div class="list-row clickable" data-notification-view="${n.view}" data-notification-id="${n.itemId||''}" data-notification-key="${esc(n.id)}"><div><strong>${esc(n.title)}</strong><small>${esc(n.text)}</small></div><span class="pill ${n.priority||''}">${esc(n.priority||'')}</span></div>`).join(''):empty('Nothing needs your attention.');
  const docs=[...d.docs].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).slice(0,3);$('#recentKnowledge').innerHTML=docs.length?docs.map(knowledgeCard).join(''):empty('No knowledge items yet.');}
function listRow(c,id,title,sub,badge=''){return `<div class="list-row clickable" data-open="${c}" data-id="${id}"><div><strong>${esc(title)}</strong><small>${esc(sub)}</small></div><span class="pill ${esc(badge)}">${esc(badge)}</span></div>`}
function renderCommunications(){let items=[...state.data.updates].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));if(state.commFilter==='mandatory')items=items.filter(x=>x.mandatory);else if(state.commFilter==='unread')items=items.filter(isUnread);else if(state.commFilter!=='all')items=items.filter(x=>x.priority===state.commFilter);$('#communicationsList').innerHTML=items.length?items.map(u=>`<article class="comm-card" data-open="updates" data-id="${u.id}"><div class="comm-date">${fmt(u.createdAt)}${!isUnread(u)?'<br><span class="pill active">Read</span>':''}</div><div><div class="meta"><span>${esc(u.category||'Update')}</span><span>Owner: ${esc(u.owner||'—')}</span>${u.approvalStatus==='pending'?'<span class="pill pending">Pending approval</span>':''}</div><h3>${esc(u.title)}</h3><p>${esc(u.summary)}</p></div><div class="comm-flags">${u.mandatory?'<span class="flag">Required</span>':''}${u.pinned?'<span class="flag">Pinned</span>':''}<span class="pill ${esc(u.priority)}">${esc(u.priority||'')}</span></div></article>`).join(''):empty('No communications match this filter.');}
function knowledgeCard(d){return `<article class="knowledge-card" data-open="docs" data-id="${d.id}"><span class="eyebrow">${esc(d.type||'KNOWLEDGE')}</span><h3>${esc(d.title)}</h3><p>${esc((d.content||'').slice(0,170))}${(d.content||'').length>170?'…':''}</p><div class="card-footer"><span>v${d.version||1} · ${esc(d.owner||'')}</span><span>${d.reviewDate?`Review ${fmt(d.reviewDate)}`:esc(d.status||'')}</span></div></article>`}
function renderKnowledge(){let items=[...state.data.docs].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt));if(state.docFilter!=='all')items=items.filter(x=>x.type===state.docFilter);$('#knowledgeList').innerHTML=items.length?items.map(knowledgeCard).join(''):empty('No knowledge items match this filter.');}
function renderLearning(){let courses=[...state.data.courses];if(state.courseFilter==='inprogress')courses=courses.filter(c=>progressOf(c).percent>0&&!progressOf(c).completed);if(state.courseFilter==='complete')courses=courses.filter(c=>progressOf(c).completed);if(state.courseFilter==='overdue')courses=courses.filter(c=>!progressOf(c).completed&&c.dueDate&&new Date(c.dueDate)<new Date());const avg=courses.length?Math.round(state.data.courses.reduce((s,c)=>s+progressOf(c).percent,0)/state.data.courses.length):0;$('#learningOverall').textContent=`${avg}%`;$('#courseGrid').innerHTML=courses.length?courses.map(c=>`<article class="course-card" data-course-id="${c.id}"><span class="eyebrow">${c.required?'REQUIRED LEARNING':'LEARNING'}</span><h3>${esc(c.title)}</h3><p>${esc((c.description||'').slice(0,180))}</p><div class="progress-track"><div class="progress-bar" style="width:${progressOf(c).percent}%"></div></div><div class="course-meta"><span>${progressOf(c).percent}% complete</span><span>${c.dueDate?`Due ${fmt(c.dueDate)}`:'No due date'}</span></div></article>`).join(''):empty('No courses in this view.');}
function renderDecisions(){const items=[...state.data.decisions].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));$('#decisionList').innerHTML=items.length?items.map(d=>`<article class="decision-card" data-open="decisions" data-id="${d.id}"><div class="meta"><span>${fmt(d.createdAt)}</span><span class="pill ${esc(d.status)}">${esc(d.status||'')}</span>${d.approvalStatus==='pending'?'<span class="pill pending">Pending approval</span>':''}</div><h3>${esc(d.decision)}</h3><div class="decision-cols"><div><strong>Why</strong><br>${esc((d.reason||'').slice(0,400))}</div><div><strong>Impact</strong><br>${esc((d.impact||'').slice(0,400))}</div></div><div class="meta" style="margin-top:15px"><span>Owner: ${esc(d.owner||'')}</span><span>${d.reviewDate?`Review ${fmt(d.reviewDate)}`:''}</span></div></article>`).join(''):empty('No decisions recorded yet.');}
function renderNotifications(){const n=toArray(state.data.notifications);$('#notificationList').innerHTML=n.length?n.map(x=>`<div class="notification-item" data-notification-view="${x.view}" data-notification-id="${x.itemId||''}" data-notification-key="${esc(x.id)}"><strong>${esc(x.title)}</strong><span>${esc(x.text)}</span></div>`).join(''):empty('You are all caught up.');}
function openDetail(collection,id){const item=state.data[collection]?.find(x=>x.id===id);if(!item)return;state.detail={collection,id};const isU=collection==='updates',isD=collection==='docs';const title=isU?item.title:isD?item.title:item.decision;const body=isU?(item.details||item.summary):isD?item.content:`${item.reason||''}\n\nImpact: ${item.impact||''}`;const type=isU?item.category:isD?item.type:'Decision';const acks=toArray(item.acknowledgements);const canEdit=['editor','admin'].includes(state.data.me.role);$('#itemModalBody').innerHTML=`<div class="detail-hero"><span class="eyebrow light">${esc(type||collection)}</span><h2>${esc(title)}</h2><p>${esc(body||'').replace(/\n/g,'<br>')}</p></div><div class="detail-grid"><div class="detail-cell"><small>Owner</small><strong>${esc(item.owner||'—')}</strong></div><div class="detail-cell"><small>Status</small><strong>${esc(item.status||'—')}</strong></div><div class="detail-cell"><small>Last change</small><strong>${fmt(item.updatedAt||item.createdAt)}</strong></div><div class="detail-cell"><small>Review</small><strong>${item.reviewDate?fmt(item.reviewDate):'Not set'}</strong></div></div><div class="detail-actions">${item.link?`<a class="btn ghost" href="${esc(item.link)}" target="_blank" rel="noopener">Open related resource ↗</a>`:''}${isU&&isUnread(item)?`<button class="btn primary" data-ack="${item.id}">${item.mandatory?'I have read & understood':'Mark as read'}</button>`:''}${canEdit?`<button class="btn dark" data-edit="${collection}" data-edit-id="${item.id}">Edit</button>`:''}${state.data.me.role==='admin'?`<button class="btn danger" data-archive="${collection}" data-archive-id="${item.id}">Archive</button>`:''}</div>${isU?`<div class="admin-section"><h3>Acknowledgements (${acks.length})</h3>${acks.length?acks.map(a=>`<div class="list-row"><div><strong>${esc(a.name)}</strong><small>${esc(a.email||'')} · ${fmtTime(a.at)}</small></div></div>`).join(''):'<p class="muted">No acknowledgements yet.</p>'}</div>`:''}<div class="admin-section"><h3>Change history</h3><div class="history-list">${toArray(item.history).slice().reverse().map(h=>`<div class="history-item"><strong>${esc(h.actor||'Unknown')}</strong> ${esc(h.action||'changed')} · ${fmtTime(h.at)}</div>`).join('')||'<span class="muted">No history.</span>'}</div></div>`;$('#itemModal').showModal();}
const formDefs={updates:[['title','Title','text'],['summary','Summary','textarea'],['details','Additional details','textarea'],['category','Category','select',['Announcement','Operational Update','Process Change','Risk','Meeting Outcome','Customer Update','Project Update']],['priority','Priority','select',['Critical','High','Medium','Low']],['owner','Owner','text'],['status','Status','select',['Draft','Active','Archived']],['reviewDate','Review date','date'],['expiresAt','Expiry date','date'],['link','Related link','url'],['mandatory','Require read & understood','checkbox'],['pinned','Pin to Home','checkbox'],['targetGroupIds','Call Center groups','groups']],docs:[['title','Title','text'],['content','Content','textarea'],['type','Type','select',['SOP','Reference','FAQ','Project','Meeting Notes']],['owner','Owner','text'],['status','Status','select',['Draft','Active','Archived']],['reviewDate','Review date','date'],['link','Related link','url'],['targetGroupIds','Call Center groups','groups']],decisions:[['decision','Decision','textarea'],['reason','Why this decision','textarea'],['impact','Impact / what changes','textarea'],['owner','Owner','text'],['status','Status','select',['Active','Superseded','Archived']],['reviewDate','Review date','date'],['link','Related source','url'],['targetGroupIds','Call Center groups','groups']]};
function openEditor(collection,id=null){const item=id?state.data[collection].find(x=>x.id===id):{};$('#editorEyebrow').textContent=id?'EDIT':'NEW';$('#editorTitle').textContent=collection==='updates'?(id?'Edit communication':'Create communication'):collection==='docs'?(id?'Edit knowledge':'Create knowledge'):id?'Edit decision':'Record decision';$('#editorForm').dataset.collection=collection;$('#editorForm').dataset.id=id||'';$('#editorFields').innerHTML=formDefs[collection].map(([k,l,t,opts])=>renderField(k,l,t,opts,item?.[k])).join('');$('#editorModal').showModal();}
function renderField(k,l,t,opts,val){if(t==='textarea')return `<div class="field"><label>${l}</label><textarea name="${k}" ${['title','decision'].includes(k)?'required':''}>${esc(val||'')}</textarea></div>`;if(t==='select')return `<div class="field"><label>${l}</label><select name="${k}">${opts.map(o=>`<option ${o===val?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;if(t==='checkbox')return `<div class="field"><label class="check-row"><input name="${k}" type="checkbox" ${val?'checked':''}>${l}</label></div>`;if(t==='groups')return `<div class="field"><label>${l}</label><div class="multi-check">${state.data.groups.length?state.data.groups.map(g=>`<label><input type="checkbox" name="${k}" value="${g.id}" ${toArray(val).includes(g.id)?'checked':''}>${esc(g.name)}</label>`).join(''):'<span class="muted">No groups created yet.</span>'}</div></div>`;return `<div class="field"><label>${l}</label><input name="${k}" type="${t}" value="${esc(val||'')}" ${['title','decision'].includes(k)?'required':''}></div>`}
async function saveEditor(e){e.preventDefault();const fd=new FormData(e.target),collection=e.target.dataset.collection,id=e.target.dataset.id;const item={};for(const [k,,t] of formDefs[collection]){if(t==='checkbox')item[k]=fd.has(k);else if(t==='groups')item[k]=fd.getAll(k);else item[k]=fd.get(k)||'';}if(id)item.id=id;try{const out=await api('item',{method:id?'PUT':'POST',body:JSON.stringify({collection,item})});state.data=out.data;$('#editorModal').close();renderAll();toast(out.item?.approvalStatus==='pending'?'Saved and sent for approval':'Saved');}catch(e){toast(e.message)}}
async function ack(id){try{const out=await api('ack',{method:'POST',body:JSON.stringify({updateId:id})});state.data=out.data;$('#itemModal').close();renderAll();toast('Acknowledged');}catch(e){toast(e.message)}}
async function archive(collection,id){if(!confirm('Archive this item? It will remain in history.'))return;try{const out=await api('item',{method:'DELETE',body:JSON.stringify({collection,id})});state.data=out.data;$('#itemModal').close();renderAll();toast('Archived');}catch(e){toast(e.message)}}
function openCourse(id){const c=state.data.courses.find(x=>x.id===id);if(!c)return;const p=progressOf(c);$('#courseModalBody').innerHTML=`<div class="course-head"><div><span class="eyebrow">${c.required?'REQUIRED LEARNING':'LEARNING'}</span><h2>${esc(c.title)}</h2><p class="muted">${esc(c.description||'')}</p></div><div class="learning-progress-big"><strong>${p.percent}%</strong><span>${p.completed?'completed':'complete'}</span></div></div><div class="progress-track"><div class="progress-bar" style="width:${p.percent}%"></div></div><div class="course-meta"><span>${p.completedCount}/${p.total} modules complete</span><span>${c.dueDate?`Due ${fmt(c.dueDate)}`:'No due date'}</span></div><div class="module-list">${toArray(c.modules).map((m,i)=>moduleRow(c,m,i)).join('')||empty('No modules yet.')}</div>`;$('#courseModal').showModal();}
function moduleDone(c,m){return !!state.data.progress?.modules?.[`${c.id}:${m.id}`]?.completed}
function moduleRow(c,m,i){const done=moduleDone(c,m);return `<div class="module-row ${done?'done':''}"><div class="module-num">${done?'✓':i+1}</div><div><strong>${esc(m.title)}</strong><div class="muted" style="font-size:12px;margin-top:4px">${esc(m.type)}</div></div><div>${m.type==='resource'?`<button class="small-btn purple" data-open-resource="${m.resourceId}" data-course="${c.id}" data-module="${m.id}">Open</button>`:m.type==='quiz'?`<button class="small-btn purple" data-start-quiz="${m.quizId}" data-course="${c.id}">Take quiz</button>`:m.type==='link'?`<button class="small-btn purple" data-open-link="${esc(m.link)}" data-course="${c.id}" data-module="${m.id}">Open link</button>`:`<button class="small-btn purple" data-show-text="${c.id}:${m.id}">Read</button>`}${done?' <span class="pill active">Complete</span>':''}</div></div>${m.type==='text'?`<div id="text-${c.id}-${m.id}" class="admin-section hidden" style="grid-column:1/-1"><p>${esc(m.text||'').replace(/\n/g,'<br>')}</p><button class="btn primary" data-complete-module="${c.id}" data-module="${m.id}">Mark complete</button></div>`:''}`}
async function openResource(resourceId,courseId,moduleId){try{toast('Opening resource…');const out=await api('learning/resource-open',{method:'POST',body:JSON.stringify({resourceId})});const bytes=Uint8Array.from(atob(out.dataBase64),c=>c.charCodeAt(0));const blob=new Blob([bytes],{type:out.resource.mimeType});const url=URL.createObjectURL(blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);if(courseId&&moduleId)await completeModule(courseId,moduleId,false);toast('Resource opened and tracked');}catch(e){toast(e.message)}}
async function completeModule(courseId,moduleId,notify=true){try{const out=await api('learning/module-complete',{method:'POST',body:JSON.stringify({courseId,moduleId})});state.data.progress=out.progress;const c=state.data.courses.find(x=>x.id===courseId);if(c)c.progress=out.courseProgress;renderLearning();openCourse(courseId);if(notify)toast('Module completed');}catch(e){toast(e.message)}}
async function startQuiz(quizId,courseId){try{const out=await api('learning/quiz-start',{method:'POST',body:JSON.stringify({quizId})});const q=out.quiz;$('#courseModalBody').innerHTML=`<span class="eyebrow">QUIZ</span><h2>${esc(q.title)}</h2><p class="muted">Pass mark ${q.passMark}% · Maximum ${q.maxAttempts} attempts</p><form id="quizForm" data-session="${out.sessionId}" data-course="${courseId}">${q.questions.map((x,i)=>`<div class="quiz-question"><strong>${i+1}. ${esc(x.prompt)}</strong>${x.options.map((o,j)=>`<label class="quiz-option"><input type="${x.type==='multiple'?'checkbox':'radio'}" name="q_${x.id}" value="${j}"><span>${esc(o)}</span></label>`).join('')}</div>`).join('')}<button class="btn primary" type="submit">Submit quiz</button></form>`;}catch(e){toast(e.message)}}
async function submitQuiz(e){e.preventDefault();const f=e.target,answers={};f.querySelectorAll('input:checked').forEach(i=>{const id=i.name.replace('q_','');(answers[id]||=[]).push(Number(i.value));});try{const out=await api('learning/quiz-submit',{method:'POST',body:JSON.stringify({sessionId:f.dataset.session,answers})});state.data.progress=out.progress;await refreshData();$('#courseModalBody').innerHTML=`<div class="detail-hero"><span class="eyebrow light">QUIZ RESULT</span><h2>${out.score}%</h2><p class="${out.passed?'result-good':'result-bad'}" style="color:white">${out.passed?'Passed':'Not passed yet'}</p></div><div class="admin-section"><h3>Feedback</h3>${out.results.map((r,i)=>`<div class="history-item"><strong>Question ${i+1}: ${r.correct?'Correct':'Incorrect'}</strong>${r.explanation?`<div class="muted" style="margin-top:5px">${esc(r.explanation)}</div>`:''}</div>`).join('')}</div><button class="btn primary" data-course-back="${f.dataset.course}">Back to course</button>`;}catch(e){toast(e.message)}}
async function refreshData(){const out=await api('data');state.data=out.data;updateProfile();renderAll();}
function search(q){q=q.trim().toLowerCase();if(!q){setView('home');return}const results=[];state.data.updates.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(q))results.push({c:'updates',id:x.id,title:x.title,sub:x.summary})});state.data.docs.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(q))results.push({c:'docs',id:x.id,title:x.title,sub:x.content})});state.data.decisions.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(q))results.push({c:'decisions',id:x.id,title:x.decision,sub:x.reason})});state.data.courses.forEach(x=>{if(JSON.stringify(x).toLowerCase().includes(q))results.push({c:'course',id:x.id,title:x.title,sub:x.description})});$('#searchCount').textContent=`${results.length} found`;$('#searchResults').innerHTML=results.length?results.map(x=>x.c==='course'?`<div class="list-row clickable" data-course-id="${x.id}"><div><strong>${esc(x.title)}</strong><small>Learning · ${esc((x.sub||'').slice(0,120))}</small></div></div>`:listRow(x.c,x.id,x.title,(x.sub||'').slice(0,140),'Open')).join(''):empty('No matching content.');setView('search');}
async function loadAdminData(){if(state.data.me.role!=='admin')return;try{const u=await api('admin/users');state.adminUsers=u;renderAdmin();}catch(e){toast(e.message)}}
async function loadAnalytics(){try{state.analytics=await api('admin/analytics');renderAdmin();}catch(e){toast(e.message)}}
function renderAdmin(){const t=state.adminTab,c=$('#adminContent');if(t==='overview'){const pending=[...state.data.updates,...state.data.docs,...state.data.decisions].filter(x=>x.approvalStatus==='pending').length,pendingUsers=state.adminUsers?.users?.filter(x=>x.status==='pending').length||0;c.innerHTML=`<div class="admin-grid">${[[state.adminUsers?.users?.length||0,'Users'],[state.data.groups.length,'Call Center groups'],[pending,'Content approvals'],[pendingUsers,'Account approvals']].map(([n,l])=>`<div class="admin-stat"><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><div class="admin-section"><h3>Admin control center</h3><p class="muted">Manage users, groups, approvals, learning assignments, reports, and audit history from the tabs above.</p></div>`;}
  if(t==='users')renderAdminUsers(c);if(t==='groups')renderAdminGroups(c);if(t==='approvals')renderApprovals(c);if(t==='learning')renderLearningAdmin(c);if(t==='reports')renderReports(c);if(t==='audit')renderAudit(c);}
function renderAdminUsers(c){const users=state.adminUsers?.users||[];c.innerHTML=`<div class="admin-section"><div class="section-heading"><div><h3>Users</h3><p class="muted">New members start as Viewer. Promote or demote access here.</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Groups</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${esc(u.email)}</td><td><select data-user-role="${u.id}"><option value="viewer" ${u.role==='viewer'?'selected':''}>Viewer</option><option value="editor" ${u.role==='editor'?'selected':''}>Editor</option><option value="admin" ${u.role==='admin'?'selected':''}>Admin</option></select></td><td><span class="pill ${u.status}">${esc(u.status)}</span></td><td>${toArray(u.groupIds).map(id=>esc(state.data.groups.find(g=>g.id===id)?.name||'')).filter(Boolean).join(', ')||'—'}</td><td class="admin-actions"><button class="small-btn" data-manage-groups="${u.id}">Groups</button>${u.status!=='active'?`<button class="small-btn purple" data-user-status="${u.id}" data-status="active">Approve</button>`:''}${u.status==='active'&&u.id!==state.data.me.id?`<button class="small-btn" data-user-status="${u.id}" data-status="suspended">Suspend</button>`:''}<button class="small-btn" data-reset-user="${u.id}">Reset password</button></td></tr>`).join('')}</tbody></table></div></div>${state.adminUsers?.resetRequests?.some(r=>r.status==='open')?`<div class="admin-section"><h3>Password reset requests</h3>${state.adminUsers.resetRequests.filter(r=>r.status==='open').map(r=>`<div class="list-row"><div><strong>${esc(r.email)}</strong><small>Requested ${fmtTime(r.createdAt)}</small></div><button class="small-btn" data-reset-request-email="${esc(r.email)}">Reset</button></div>`).join('')}</div>`:''}`;}
function renderAdminGroups(c){c.innerHTML=`<div class="admin-section"><div class="section-heading"><div><h3>Centralized Call Center groups</h3><p class="muted">Use groups only to organize the Centralized Call Center team and target communications or learning.</p></div><button class="btn primary" data-new-group>+ New group</button></div>${state.data.groups.length?state.data.groups.map(g=>`<div class="list-row"><div><strong>${esc(g.name)}</strong><small>${esc(g.description||'')}</small></div><div class="admin-actions"><button class="small-btn" data-edit-group="${g.id}">Edit</button><button class="small-btn" data-delete-group="${g.id}">Delete</button></div></div>`).join(''):empty('No groups yet.')}</div>`}
function renderApprovals(c){const items=[...state.data.updates.map(x=>({...x,_c:'updates',_t:x.title})),...state.data.docs.map(x=>({...x,_c:'docs',_t:x.title})),...state.data.decisions.map(x=>({...x,_c:'decisions',_t:x.decision}))].filter(x=>x.approvalStatus==='pending');c.innerHTML=`<div class="admin-section"><h3>Content approvals</h3>${items.length?items.map(x=>`<div class="list-row"><div><strong>${esc(x._t)}</strong><small>${esc(x._c)} · Owner ${esc(x.owner||'')}</small></div><div class="admin-actions"><button class="small-btn" data-open="${x._c}" data-id="${x.id}">Review</button><button class="small-btn purple" data-approve="${x._c}" data-approve-id="${x.id}" data-decision="approved">Approve</button><button class="small-btn" data-approve="${x._c}" data-approve-id="${x.id}" data-decision="rejected">Reject</button></div></div>`).join(''):empty('No content is waiting for approval.')}</div>`}
function resourceUsage(resourceId){return state.data.courses.filter(c=>toArray(c.modules).some(m=>m.type==='resource'&&m.resourceId===resourceId));}
function fileSizeLabel(bytes){const n=Number(bytes||0);return n>=1048576?`${(n/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(n/1024))} KB`;}
function renderLearningAdmin(c){
  const activeResources=state.data.resources.filter(r=>(r.status||'Active')!=='Archived'), archivedResources=state.data.resources.filter(r=>r.status==='Archived');
  const resourceRows=(items,archived=false)=>items.map(r=>{const used=resourceUsage(r.id);return `<div class="resource-card ${archived?'is-archived':''}"><div class="resource-icon">${r.mimeType?.includes('pdf')?'PDF':r.mimeType?.includes('presentation')||r.fileName?.match(/\.pptx?$/i)?'PPT':r.mimeType?.includes('word')||r.fileName?.match(/\.docx?$/i)?'DOC':'FILE'}</div><div class="resource-main"><div class="resource-title-row"><strong>${esc(r.title)}</strong><span class="pill ${archived?'Archived':'active'}">${archived?'Archived':'Active'}</span></div><small>${esc(r.fileName)} · ${fileSizeLabel(r.size)} · v${Number(r.version||1)}</small><small>${esc(r.category||'General')}${used.length?` · Used in ${used.length} course${used.length===1?'':'s'}`:' · Not in a course yet'}${r.reviewDate?` · Review ${fmt(r.reviewDate)}`:''}</small>${r.description?`<p class="resource-description">${esc(r.description)}</p>`:''}</div><div class="resource-actions"><button class="small-btn" data-preview-resource="${r.id}">Open</button><button class="small-btn" data-edit-resource="${r.id}">Edit</button><button class="small-btn" data-replace-resource="${r.id}">Replace file</button>${archived?`<button class="small-btn purple" data-resource-action="restore" data-resource-id="${r.id}">Restore</button>`:`<button class="small-btn" data-resource-action="archive" data-resource-id="${r.id}">Archive</button>`}<button class="small-btn danger-outline" data-resource-action="delete" data-resource-id="${r.id}">Delete</button></div></div>`}).join('');
  c.innerHTML=`<div class="admin-section content-library"><div class="section-heading"><div><span class="eyebrow">LEARNING CONTENT</span><h3>Content Library</h3><p class="muted">Upload, organize, replace, archive, and remove learning documents. Existing course usage is protected from accidental deletion.</p></div><button class="btn primary" data-upload-resource>+ Upload content</button></div><div class="library-stats"><span><strong>${activeResources.length}</strong> active</span><span><strong>${archivedResources.length}</strong> archived</span><span><strong>${activeResources.filter(r=>resourceUsage(r.id).length).length}</strong> used in courses</span></div><div class="resource-list">${resourceRows(activeResources)||empty('No learning content has been uploaded yet.')}</div>${archivedResources.length?`<details class="archive-drawer"><summary>Archived content (${archivedResources.length})</summary><div class="resource-list">${resourceRows(archivedResources,true)}</div></details>`:''}</div><div class="three-col"><div class="admin-section"><h3>Question bank</h3><p class="muted">Reusable quiz questions with explanations.</p><button class="btn primary" data-new-question>+ Question</button><div style="margin-top:14px"><strong>${state.data.questionBank?.length||0}</strong> questions</div></div><div class="admin-section"><h3>Quizzes</h3><p class="muted">Passing scores, attempts, randomization and feedback.</p><button class="btn primary" data-new-quiz>+ Quiz</button><div style="margin-top:14px"><strong>${state.data.quizzes?.length||0}</strong> quizzes</div></div><div class="admin-section"><h3>Courses</h3><p class="muted">Create structured learning from content, quizzes, text and links.</p><button class="btn primary" data-new-course>+ Course</button><div style="margin-top:14px"><strong>${state.data.courses.filter(x=>x.status!=='Archived').length}</strong> courses</div></div></div><div class="admin-section"><div class="section-heading"><div><h3>Courses</h3><p class="muted">Build learning paths from documents, text, links and quizzes.</p></div><button class="btn primary" data-new-course>+ Course</button></div>${state.data.courses.filter(c=>c.status!=='Archived').length?state.data.courses.filter(c=>c.status!=='Archived').map(c=>`<div class="list-row"><div><strong>${esc(c.title)}</strong><small>${toArray(c.modules).length} modules · ${c.required?'Required':'Optional'}${c.dueDate?` · Due ${fmt(c.dueDate)}`:''}</small></div><div class="admin-actions"><button class="small-btn" data-course-id="${c.id}">Preview</button><button class="small-btn" data-edit-course="${c.id}">Edit</button></div></div>`).join(''):empty('No courses yet.')}</div><div class="admin-section"><h3>Question bank</h3>${state.data.questionBank?.length?state.data.questionBank.slice(0,20).map(q=>`<div class="list-row"><div><strong>${esc(q.prompt)}</strong><small>${esc(q.type)} · ${toArray(q.options).length} options</small></div></div>`).join(''):empty('No questions yet.')}</div><div class="admin-section"><h3>Quizzes</h3>${state.data.quizzes?.length?state.data.quizzes.map(q=>`<div class="list-row"><div><strong>${esc(q.title)}</strong><small>${toArray(q.questionIds).length} questions · Pass ${q.passMark}% · ${q.maxAttempts} attempts</small></div></div>`).join(''):empty('No quizzes yet.')}</div>`;
}
function renderReports(c){if(!state.analytics){c.innerHTML=`<div class="admin-section"><h3>Reports & analytics</h3><p class="muted">Learning completion, quiz performance, acknowledgement compliance and exportable reports.</p><button class="btn primary" data-load-analytics>Load reports</button></div>`;return}const a=state.analytics,completed=a.learning.filter(x=>x.completed).length,overdue=a.learning.filter(x=>x.overdue).length,ack=a.acknowledgements.length?Math.round(a.acknowledgements.filter(x=>x.acknowledged).length/a.acknowledgements.length*100):100,avg=a.quizAttempts.length?Math.round(a.quizAttempts.reduce((s,x)=>s+x.score,0)/a.quizAttempts.length):0;c.innerHTML=`<div class="admin-grid">${[[completed,'Completed assignments'],[overdue,'Overdue assignments'],[ack+'%','Mandatory acknowledgement'],[avg+'%','Average quiz score']].map(([n,l])=>`<div class="admin-stat"><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><div class="admin-section"><div class="section-heading"><h3>Export reports</h3></div><div class="admin-actions"><button class="btn ghost" data-export="learning">Learning CSV</button><button class="btn ghost" data-export="acknowledgements">Acknowledgements CSV</button><button class="btn ghost" data-export="quizAttempts">Quiz attempts CSV</button><button class="btn ghost" data-export="resourceOpens">Document opens CSV</button></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Learner</th><th>Course</th><th>Progress</th><th>Due</th><th>Status</th></tr></thead><tbody>${a.learning.slice(0,100).map(r=>`<tr><td>${esc(r.name)}<br><small>${esc(r.email)}</small></td><td>${esc(r.course)}</td><td>${r.progress}%</td><td>${r.dueDate?fmt(r.dueDate):'—'}</td><td><span class="pill ${r.overdue?'Critical':r.completed?'active':''}">${r.completed?'Complete':r.overdue?'Overdue':'In progress'}</span></td></tr>`).join('')}</tbody></table></div>`}
function renderAudit(c){const items=toArray(state.data.activity);c.innerHTML=`<div class="admin-section"><h3>Audit trail</h3>${items.length?items.map(a=>`<div class="list-row"><div><strong>${esc(a.actor)} ${esc(a.action)} ${esc(a.label)}</strong><small>${esc(a.collection)}${a.detail?` · ${esc(a.detail)}`:''}</small></div><span class="muted">${fmtTime(a.at)}</span></div>`).join(''):empty('No recorded activity.')}</div>`}
function openAdminModal(html){$('#adminModalBody').innerHTML=html;$('#adminModal').showModal();}
function groupModal(g=null){openAdminModal(`<span class="eyebrow">CALL CENTER GROUP</span><h2>${g?'Edit group':'New group'}</h2><form id="groupForm" data-id="${g?.id||''}" class="form-stack"><label>Name<input name="name" required value="${esc(g?.name||'')}"></label><label>Description<textarea name="description">${esc(g?.description||'')}</textarea></label><button class="btn primary" type="submit">Save group</button></form>`)}
function manageGroupsModal(userId){const u=state.adminUsers.users.find(x=>x.id===userId);openAdminModal(`<span class="eyebrow">USER GROUPS</span><h2>${esc(u.name)}</h2><form id="userGroupsForm" data-id="${u.id}" class="form-stack"><div class="multi-check">${state.data.groups.map(g=>`<label><input type="checkbox" name="groups" value="${g.id}" ${toArray(u.groupIds).includes(g.id)?'checked':''}>${esc(g.name)}</label>`).join('')||'<span class="muted">Create a Call Center group first.</span>'}</div><button class="btn primary" type="submit">Save groups</button></form>`)}
function resetUserModal(userId){const u=state.adminUsers.users.find(x=>x.id===userId);openAdminModal(`<span class="eyebrow">PASSWORD RESET</span><h2>${esc(u.name)}</h2><p class="muted">Set a temporary password and send it to the user through an approved channel. Their existing sessions will be signed out.</p><form id="resetUserForm" data-id="${u.id}" class="form-stack"><label>Temporary password<input name="password" type="password" minlength="10" required placeholder="10+ characters, letter + number"></label><button class="btn primary" type="submit">Reset password</button></form>`)}
function uploadResourceModal(r=null,replace=false){openAdminModal(`<span class="eyebrow">LEARNING CONTENT</span><h2>${replace?'Replace file':r?'Edit content':'Upload content'}</h2><form id="resourceForm" data-id="${r?.id||''}" data-mode="${replace?'replace':r?'edit':'upload'}" class="form-stack"><label>Display title<input name="title" required value="${esc(r?.title||'')}"></label><label>Description<textarea name="description" placeholder="What should learners know about this resource?">${esc(r?.description||'')}</textarea></label><label>Category<input name="category" value="${esc(r?.category||'General')}" placeholder="e.g. Product refresher, SOP, Policy"></label><label>Review date<input name="reviewDate" type="date" value="${esc(r?.reviewDate||'')}"></label>${replace||!r?`<label>${replace?'New file':'File'}<input name="file" type="file" required accept=".pdf,.doc,.docx,.ppt,.pptx,.txt,.html,.csv,.png,.jpg,.jpeg"></label><p class="muted">The default upload limit is 4 MB. Replacing a file keeps the same learning resource and increments its version.</p>`:'<p class="muted">Editing metadata does not replace the uploaded file.</p>'}<button class="btn primary" type="submit">${replace?'Replace file':r?'Save details':'Upload content'}</button></form>`)}
async function resourceAction(id,action){const r=state.data.resources.find(x=>x.id===id);if(!r)return;if(action==='archive'&&!confirm(`Archive “${r.title}”? Existing courses can still reference it, but it will no longer appear when adding new modules.`))return;if(action==='delete'&&!confirm(`Permanently delete “${r.title}”? This cannot be undone. If it is used in a course, deletion will be blocked.`))return;try{const out=await api('learning/resource-manage',{method:'POST',body:JSON.stringify({id,action})});if(out.data)state.data=out.data;else await refreshData();renderAdmin();toast(action==='delete'?'Document deleted':action==='archive'?'Document archived':'Document restored');}catch(e){toast(e.message)}}
async function inlineUploadResource(file,moduleIndex){if(!file)return;const m=window.__courseModules?.[moduleIndex];const title=(m?.title&&m.title!=='New module')?m.title:file.name.replace(/\.[^.]+$/,'');const reader=new FileReader();reader.onload=async()=>{try{const dataBase64=String(reader.result).split(',')[1];const out=await api('learning/resource-upload',{method:'POST',body:JSON.stringify({title,fileName:file.name,mimeType:file.type,dataBase64,category:'Course upload'})});state.data=out.data;window.__courseModules[moduleIndex].resourceId=out.resource.id;renderModuleBuilder();toast('Document uploaded and selected');}catch(err){toast(err.message)}};reader.readAsDataURL(file);}
function questionModal(){openAdminModal(`<span class="eyebrow">QUESTION BANK</span><h2>New question</h2><form id="questionForm" class="form-stack"><label>Question<textarea name="prompt" required></textarea></label><label>Type<select name="type"><option value="single">Single choice</option><option value="multiple">Multiple select</option><option value="truefalse">True / False</option></select></label><label>Options (one per line)<textarea name="options" placeholder="Option A\nOption B\nOption C"></textarea></label><label>Correct option numbers (1-based, comma separated)<input name="correct" placeholder="1 or 1,3"></label><label>Explanation<textarea name="explanation"></textarea></label><label>Tags (comma separated)<input name="tags"></label><button class="btn primary" type="submit">Add question</button></form>`)}
function quizModal(){openAdminModal(`<span class="eyebrow">QUIZ</span><h2>Create quiz</h2><form id="quizAdminForm" class="form-stack"><label>Title<input name="title" required></label><label>Description<textarea name="description"></textarea></label><label>Pass mark (%)<input name="passMark" type="number" value="80" min="0" max="100"></label><label>Maximum attempts<input name="maxAttempts" type="number" value="3" min="1" max="20"></label><label>Random question count (0 = all)<input name="questionCount" type="number" value="0" min="0"></label><div class="field"><label>Questions</label><div class="multi-check">${toArray(state.data.questionBank).map(q=>`<label><input type="checkbox" name="questionIds" value="${q.id}">${esc(q.prompt.slice(0,60))}</label>`).join('')||'<span class="muted">Add questions first.</span>'}</div></div><label class="check-row"><input type="checkbox" name="shuffle" checked> Randomize order</label><label class="check-row"><input type="checkbox" name="showFeedback" checked> Show explanations after submission</label><button class="btn primary" type="submit">Create quiz</button></form>`)}
function courseModalAdmin(c=null){const moduleText=c?JSON.stringify(c.modules,null,2):'';openAdminModal(`<span class="eyebrow">LEARNING COURSE</span><h2>${c?'Edit course':'Create course'}</h2><form id="courseAdminForm" data-id="${c?.id||''}" class="form-stack"><label>Title<input name="title" required value="${esc(c?.title||'')}"></label><label>Description<textarea name="description">${esc(c?.description||'')}</textarea></label><label>Status<select name="status"><option ${c?.status!=='Draft'?'selected':''}>Active</option><option ${c?.status==='Draft'?'selected':''}>Draft</option></select></label><label>Due date<input name="dueDate" type="date" value="${esc(c?.dueDate||'')}"></label><label class="check-row"><input type="checkbox" name="required" ${c?.required?'checked':''}> Required learning</label><div class="field"><label>Assign to Call Center groups</label><div class="multi-check">${state.data.groups.map(g=>`<label><input type="checkbox" name="assignedGroupIds" value="${g.id}" ${toArray(c?.assignedGroupIds).includes(g.id)?'checked':''}>${esc(g.name)}</label>`).join('')||'<span class="muted">No groups; leaving blank can assign to everyone.</span>'}</div></div><div class="field"><label>Assign to specific users (optional)</label><div class="multi-check">${toArray(state.adminUsers?.users).filter(u=>u.status==='active').map(u=>`<label><input type="checkbox" name="assignedUserIds" value="${u.id}" ${toArray(c?.assignedUserIds).includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')||'<span class="muted">No active users loaded.</span>'}</div></div><div class="field"><label>Modules</label><p class="muted">Add modules below. You can mix uploaded documents, quizzes, text lessons, and links.</p><div id="moduleBuilder"></div><div class="admin-actions"><button type="button" class="small-btn" data-add-module="resource">+ Document</button><button type="button" class="small-btn" data-add-module="quiz">+ Quiz</button><button type="button" class="small-btn" data-add-module="text">+ Text</button><button type="button" class="small-btn" data-add-module="link">+ Link</button></div></div><button class="btn primary" type="submit">Save course</button></form>`);window.__courseModules=toArray(c?.modules).map(x=>({...x}));renderModuleBuilder();}
function renderModuleBuilder(){const root=$('#moduleBuilder');if(!root)return;const selectable=state.data.resources.filter(r=>(r.status||'Active')!=='Archived');root.innerHTML=window.__courseModules.map((m,i)=>`<div class="admin-section module-builder-card"><div class="section-heading"><strong>${i+1}. ${esc(m.title||'Untitled module')} <span class="pill">${esc(m.type)}</span></strong><button type="button" class="small-btn" data-remove-module="${i}">Remove</button></div><label>Title<input data-module-field="title" data-module-index="${i}" value="${esc(m.title||'')}"></label>${m.type==='resource'?`<div class="module-resource-picker"><label>Choose from Content Library<select data-module-field="resourceId" data-module-index="${i}"><option value="">Select document</option>${selectable.map(r=>`<option value="${r.id}" ${m.resourceId===r.id?'selected':''}>${esc(r.title)} · v${Number(r.version||1)}</option>`).join('')}</select></label><div class="or-divider"><span>or</span></div><label class="inline-upload-btn">Upload a new document<input type="file" data-inline-upload="${i}" accept=".pdf,.doc,.docx,.ppt,.pptx,.txt,.html,.csv,.png,.jpg,.jpeg" hidden></label>${m.resourceId?`<small class="selected-resource">Selected: ${esc(state.data.resources.find(r=>r.id===m.resourceId)?.title||'Document')}</small>`:''}</div>`:''}${m.type==='quiz'?`<label>Quiz<select data-module-field="quizId" data-module-index="${i}"><option value="">Select quiz</option>${toArray(state.data.quizzes).map(q=>`<option value="${q.id}" ${m.quizId===q.id?'selected':''}>${esc(q.title)}</option>`).join('')}</select></label>`:''}${m.type==='text'?`<label>Lesson text<textarea data-module-field="text" data-module-index="${i}">${esc(m.text||'')}</textarea></label>`:''}${m.type==='link'?`<label>Link<input data-module-field="link" data-module-index="${i}" type="url" value="${esc(m.link||'')}"></label>`:''}</div>`).join('')||'<p class="muted">No modules added yet.</p>'; }
async function adminUserAction(userId,action,payload={}){try{const out=await api('admin/user',{method:'POST',body:JSON.stringify({userId,action,...payload})});state.adminUsers.users=out.users;await refreshData();renderAdmin();toast('Updated');}catch(e){toast(e.message)}}
async function approval(collection,id,decision){try{const out=await api('approve',{method:'POST',body:JSON.stringify({collection,id,decision})});state.data=out.data;renderAll();renderAdmin();toast(decision==='approved'?'Approved':'Rejected');}catch(e){toast(e.message)}}
function csvDownload(name,rows){if(!rows?.length){toast('No data to export');return}const keys=Object.keys(rows[0]);const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;const csv=[keys.map(q).join(','),...rows.map(r=>keys.map(k=>q(r[k])).join(','))].join('\n');const blob=new Blob([csv],{type:'text/csv'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${name}-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(url)}
async function logout(callApi=true){if(callApi&&state.token)api('auth/logout',{method:'POST'}).catch(()=>{});state.token='';state.data=null;localStorage.removeItem('cccHubToken');showApp(false);setAuthPanel('login');}

// Forms
document.addEventListener('submit',async e=>{
  if(e.target.id==='loginForm'){e.preventDefault();const b=Object.fromEntries(new FormData(e.target));try{const out=await api('auth/login',{method:'POST',body:JSON.stringify(b)});state.token=out.token;localStorage.setItem('cccHubToken',state.token);await bootstrap();}catch(err){$('#authMessage').textContent=err.message}}
  if(e.target.id==='signupForm'){e.preventDefault();const b=Object.fromEntries(new FormData(e.target));if(b.password!==b.confirm){$('#authMessage').textContent='Passwords do not match.';return}delete b.confirm;try{const out=await api('auth/signup',{method:'POST',body:JSON.stringify(b)});$('#authMessage').textContent=out.message;setAuthPanel('login');}catch(err){$('#authMessage').textContent=err.message}}
  if(e.target.id==='resetForm'){e.preventDefault();try{const out=await api('auth/request-reset',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target))) });$('#authMessage').textContent=out.message;setAuthPanel('login');}catch(err){$('#authMessage').textContent=err.message}}
  if(e.target.id==='editorForm')saveEditor(e);
  if(e.target.id==='quizForm')submitQuiz(e);
  if(e.target.id==='groupForm'){e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.action=e.target.dataset.id?'update':'create';b.id=e.target.dataset.id;try{await api('admin/group',{method:'POST',body:JSON.stringify(b)});$('#adminModal').close();await refreshData();renderAdmin();toast('Group saved');}catch(err){toast(err.message)}}
  if(e.target.id==='userGroupsForm'){e.preventDefault();adminUserAction(e.target.dataset.id,'groups',{groupIds:new FormData(e.target).getAll('groups')});$('#adminModal').close();}
  if(e.target.id==='resetUserForm'){e.preventDefault();adminUserAction(e.target.dataset.id,'reset-password',{password:new FormData(e.target).get('password')});$('#adminModal').close();}
  if(e.target.id==='resourceForm'){e.preventDefault();const fd=new FormData(e.target),id=e.target.dataset.id,mode=e.target.dataset.mode;try{if(mode==='edit'){const out=await api('learning/resource-manage',{method:'POST',body:JSON.stringify({id,action:'update',title:fd.get('title'),description:fd.get('description'),category:fd.get('category'),reviewDate:fd.get('reviewDate')})});state.data=out.data;$('#adminModal').close();renderAdmin();toast('Content details updated');}else{const file=fd.get('file');if(!file||!file.size){toast('Choose a file first');return;}const reader=new FileReader();reader.onload=async()=>{const dataBase64=String(reader.result).split(',')[1];try{const out=await api('learning/resource-upload',{method:'POST',body:JSON.stringify({id:mode==='replace'?id:undefined,title:fd.get('title'),description:fd.get('description'),category:fd.get('category'),reviewDate:fd.get('reviewDate'),fileName:file.name,mimeType:file.type,dataBase64})});state.data=out.data;$('#adminModal').close();renderAdmin();toast(mode==='replace'?'File replaced':'Content uploaded');}catch(err){toast(err.message)}};reader.readAsDataURL(file);}}catch(err){toast(err.message)}}
  if(e.target.id==='questionForm'){e.preventDefault();const fd=new FormData(e.target),opts=String(fd.get('options')||'').split('\n').map(x=>x.trim()).filter(Boolean);if(fd.get('type')==='truefalse'&&!opts.length)opts.push('True','False');const correct=String(fd.get('correct')||'').split(',').map(x=>Number(x.trim())-1).filter(x=>x>=0);try{await api('learning/question',{method:'POST',body:JSON.stringify({action:'save',type:fd.get('type'),prompt:fd.get('prompt'),options:opts,correct,explanation:fd.get('explanation'),tags:String(fd.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean)})});$('#adminModal').close();await refreshData();renderAdmin();toast('Question added');}catch(err){toast(err.message)}}
  if(e.target.id==='quizAdminForm'){e.preventDefault();const fd=new FormData(e.target);try{await api('learning/quiz',{method:'POST',body:JSON.stringify({action:'save',title:fd.get('title'),description:fd.get('description'),questionIds:fd.getAll('questionIds'),passMark:fd.get('passMark'),maxAttempts:fd.get('maxAttempts'),questionCount:fd.get('questionCount'),shuffle:fd.has('shuffle'),showFeedback:fd.has('showFeedback')})});$('#adminModal').close();await refreshData();renderAdmin();toast('Quiz created');}catch(err){toast(err.message)}}
  if(e.target.id==='courseAdminForm'){e.preventDefault();const fd=new FormData(e.target),id=e.target.dataset.id;try{await api('learning/course',{method:'POST',body:JSON.stringify({action:'save',id:id||undefined,title:fd.get('title'),description:fd.get('description'),status:fd.get('status'),dueDate:fd.get('dueDate'),required:fd.has('required'),assignedGroupIds:fd.getAll('assignedGroupIds'),assignedUserIds:fd.getAll('assignedUserIds'),modules:window.__courseModules})});$('#adminModal').close();await refreshData();renderAdmin();toast('Course saved');}catch(err){toast(err.message)}}
});

document.addEventListener('click',async e=>{
  const auth=e.target.closest('[data-auth]');if(auth)setAuthPanel(auth.dataset.auth);
  const nav=e.target.closest('[data-view]');if(nav)setView(nav.dataset.view);
  const jump=e.target.closest('[data-jump]');if(jump)setView(jump.dataset.jump);
  const open=e.target.closest('[data-open]');if(open)openDetail(open.dataset.open,open.dataset.id);
  const create=e.target.closest('[data-create]');if(create)openEditor(create.dataset.create);
  const cf=e.target.closest('[data-comm-filter]');if(cf){state.commFilter=cf.dataset.commFilter;$$('[data-comm-filter]').forEach(x=>x.classList.toggle('active',x===cf));renderCommunications()}
  const df=e.target.closest('[data-doc-filter]');if(df){state.docFilter=df.dataset.docFilter;$$('[data-doc-filter]').forEach(x=>x.classList.toggle('active',x===df));renderKnowledge()}
  const lf=e.target.closest('[data-course-filter]');if(lf){state.courseFilter=lf.dataset.courseFilter;$$('[data-course-filter]').forEach(x=>x.classList.toggle('active',x===lf));renderLearning()}
  const course=e.target.closest('[data-course-id]');if(course&&!e.target.closest('[data-edit-course]'))openCourse(course.dataset.courseId);
  const ackb=e.target.closest('[data-ack]');if(ackb)ack(ackb.dataset.ack);
  const edit=e.target.closest('[data-edit]');if(edit){$('#itemModal').close();openEditor(edit.dataset.edit,edit.dataset.editId)}
  const arc=e.target.closest('[data-archive]');if(arc)archive(arc.dataset.archive,arc.dataset.archiveId);
  const nr=e.target.closest('[data-notification-view]');if(nr){const key=nr.dataset.notificationKey;$('#notificationPanel').classList.add('hidden');if(key)await dismissNotification(key);if(nr.dataset.notificationView==='learning'&&nr.dataset.notificationId){setView('learning');openCourse(nr.dataset.notificationId)}else if(nr.dataset.notificationView==='communications'&&nr.dataset.notificationId){setView('communications');openDetail('updates',nr.dataset.notificationId)}else setView(nr.dataset.notificationView)}
  if(e.target.closest('[data-close-editor]'))$('#editorModal').close();if(e.target.closest('[data-close-course]'))$('#courseModal').close();if(e.target.closest('[data-close-admin-modal]'))$('#adminModal').close();
  const res=e.target.closest('[data-open-resource]');if(res)openResource(res.dataset.openResource,res.dataset.course,res.dataset.module);
  const quiz=e.target.closest('[data-start-quiz]');if(quiz)startQuiz(quiz.dataset.startQuiz,quiz.dataset.course);
  const txt=e.target.closest('[data-show-text]');if(txt){const el=$(`#text-${txt.dataset.showText.replace(':','-')}`);el?.classList.toggle('hidden')}
  const cm=e.target.closest('[data-complete-module]');if(cm)completeModule(cm.dataset.completeModule,cm.dataset.module);
  const link=e.target.closest('[data-open-link]');if(link){window.open(link.dataset.openLink,'_blank','noopener');completeModule(link.dataset.course,link.dataset.module,false)}
  const back=e.target.closest('[data-course-back]');if(back)openCourse(back.dataset.courseBack);
  const at=e.target.closest('[data-admin-tab]');if(at){state.adminTab=at.dataset.adminTab;$$('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x===at));renderAdmin()}
  const role=e.target.closest('[data-user-role]');
  const st=e.target.closest('[data-user-status]');if(st)adminUserAction(st.dataset.userStatus,'status',{status:st.dataset.status});
  const mg=e.target.closest('[data-manage-groups]');if(mg)manageGroupsModal(mg.dataset.manageGroups);
  const ru=e.target.closest('[data-reset-user]');if(ru)resetUserModal(ru.dataset.resetUser);
  const rr=e.target.closest('[data-reset-request-email]');if(rr){const u=state.adminUsers.users.find(x=>x.email===rr.dataset.resetRequestEmail);if(u)resetUserModal(u.id)}
  if(e.target.closest('[data-new-group]'))groupModal();const eg=e.target.closest('[data-edit-group]');if(eg)groupModal(state.data.groups.find(g=>g.id===eg.dataset.editGroup));const dg=e.target.closest('[data-delete-group]');if(dg&&confirm('Delete this Call Center group?'))api('admin/group',{method:'POST',body:JSON.stringify({action:'delete',id:dg.dataset.deleteGroup})}).then(refreshData).then(renderAdmin).catch(x=>toast(x.message));
  const ap=e.target.closest('[data-approve]');if(ap)approval(ap.dataset.approve,ap.dataset.approveId,ap.dataset.decision);
  if(e.target.closest('[data-upload-resource]'))uploadResourceModal();const pr=e.target.closest('[data-preview-resource]');if(pr)openResource(pr.dataset.previewResource);const er=e.target.closest('[data-edit-resource]');if(er)uploadResourceModal(state.data.resources.find(r=>r.id===er.dataset.editResource),false);const rrpl=e.target.closest('[data-replace-resource]');if(rrpl)uploadResourceModal(state.data.resources.find(r=>r.id===rrpl.dataset.replaceResource),true);const ra=e.target.closest('[data-resource-action]');if(ra)resourceAction(ra.dataset.resourceId,ra.dataset.resourceAction);if(e.target.closest('[data-new-question]'))questionModal();if(e.target.closest('[data-new-quiz]'))quizModal();if(e.target.closest('[data-new-course]'))courseModalAdmin();const ec=e.target.closest('[data-edit-course]');if(ec)courseModalAdmin(state.data.courses.find(c=>c.id===ec.dataset.editCourse));
  const addm=e.target.closest('[data-add-module]');if(addm){window.__courseModules.push({id:crypto.randomUUID?.()||`${Date.now()}${Math.random()}`,title:'New module',type:addm.dataset.addModule,required:true});renderModuleBuilder()}
  const rmm=e.target.closest('[data-remove-module]');if(rmm){window.__courseModules.splice(Number(rmm.dataset.removeModule),1);renderModuleBuilder()}
  if(e.target.closest('[data-load-analytics]'))loadAnalytics();const ex=e.target.closest('[data-export]');if(ex)csvDownload(ex.dataset.export,state.analytics?.[ex.dataset.export]);
  if(e.target.closest('[data-clear-notifications]')){await dismissAllNotifications();return;}
  if(e.target.closest('[data-close-panel]'))$('#notificationPanel').classList.add('hidden');if(e.target.closest('[data-close-profile]'))$('#profilePanel').classList.add('hidden');
});
document.addEventListener('change',async e=>{if(e.target.matches('[data-user-role]'))adminUserAction(e.target.dataset.userRole,'role',{role:e.target.value});if(e.target.matches('[data-module-field]')){window.__courseModules[Number(e.target.dataset.moduleIndex)][e.target.dataset.moduleField]=e.target.value;}if(e.target.matches('[data-inline-upload]')){await inlineUploadResource(e.target.files?.[0],Number(e.target.dataset.inlineUpload));e.target.value='';}});
$('#quickCreate').addEventListener('click',()=>openEditor(state.view==='knowledge'?'docs':state.view==='decisions'?'decisions':'updates'));
$('#notificationButton').addEventListener('click',()=>{$('#profilePanel').classList.add('hidden');$('#notificationPanel').classList.toggle('hidden')});$('#profileButton').addEventListener('click',()=>{$('#notificationPanel').classList.add('hidden');const me=state.data.me;$('#profileInfo').innerHTML=`<div class="admin-section"><strong>${esc(me.name)}</strong><p class="muted">${esc(me.email)}</p><span class="pill">${roleName(me.role)}</span>${toArray(me.groupIds).length?`<p class="muted">Groups: ${toArray(me.groupIds).map(id=>esc(state.data.groups.find(g=>g.id===id)?.name||'')).filter(Boolean).join(', ')}</p>`:''}</div>`;$('#profilePanel').classList.toggle('hidden')});$('#logoutButton').addEventListener('click',()=>logout(true));
let stimer;$('#globalSearch').addEventListener('input',e=>{clearTimeout(stimer);stimer=setTimeout(()=>search(e.target.value),180)});
bootstrap();

// Fast, purposeful Zipline-inspired motion. Respects reduced-motion preferences.
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');revealObserver.unobserve(e.target)}}),{threshold:.08});document.addEventListener('DOMContentLoaded',()=>document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el)));}
